CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS admin_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entra_object_id text NOT NULL UNIQUE, email text NOT NULL, display_name text NOT NULL, roles text[] NOT NULL DEFAULT '{}', permissions text[] NOT NULL DEFAULT '{}', geography_scopes text[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, super_admin boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_sessions (id uuid PRIMARY KEY, admin_user_id uuid NOT NULL REFERENCES admin_users(id), expires_at timestamptz NOT NULL, revoked_at timestamptz NULL, ip_address text NULL, user_agent text NULL, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_admin_sessions_admin_user ON admin_sessions(admin_user_id);
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_admin_user_id uuid NULL REFERENCES admin_users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text NULL, outcome text NOT NULL, correlation_id text NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_audit_events_created_at ON audit_events(created_at DESC);
CREATE TABLE IF NOT EXISTS user_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL, status text NOT NULL DEFAULT 'active', verified boolean NOT NULL DEFAULT false, account_type text NOT NULL DEFAULT 'individual', geography text NULL, last_activity_at timestamptz NULL, registered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, verification_status text NOT NULL DEFAULT 'pending', status text NOT NULL DEFAULT 'active', member_count integer NOT NULL DEFAULT 0, active_listing_count integer NOT NULL DEFAULT 0, geography text NULL, registered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS food_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, status text NOT NULL DEFAULT 'active', category text NOT NULL DEFAULT 'other', total_quantity integer NOT NULL DEFAULT 0 CHECK(total_quantity >= 0), reserved_quantity integer NOT NULL DEFAULT 0 CHECK(reserved_quantity >= 0), collected_quantity integer NOT NULL DEFAULT 0 CHECK(collected_quantity >= 0), unavailable_quantity integer NOT NULL DEFAULT 0 CHECK(unavailable_quantity >= 0), geography text NULL, expires_at timestamptz NULL, CONSTRAINT food_inventory_invariant CHECK (reserved_quantity + collected_quantity + unavailable_quantity <= total_quantity));
CREATE TABLE IF NOT EXISTS pickups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), status text NOT NULL DEFAULT 'scheduled', quantity integer NOT NULL DEFAULT 0 CHECK(quantity >= 0), scheduled_at timestamptz NULL);
CREATE TABLE IF NOT EXISTS safety_incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, severity text NOT NULL DEFAULT 'medium', status text NOT NULL DEFAULT 'new', created_at timestamptz NOT NULL DEFAULT now());
